@push('scripts')
<script>
(()=>{
 const t=@json(__('bc27out')), products=@json($products), lines=@json($lines),body=document.getElementById('bc-items');let index=0,mode='product',pending;
 const modal=new bootstrap.Modal(document.getElementById('bc-picker'));
 function cell(row,value){const c=row.insertCell();c.textContent=value??'';return c;}
 function totals(){let total=0;body.querySelectorAll('tr').forEach(row=>{const qty=Number(row.querySelector('[data-field="quantity"]').value)||0;const price=Number(row.querySelector('[data-field="unit_price"]').value)||0;const value=Math.round((qty*price+Number.EPSILON)*1e4)/1e4;row.querySelector('.line-total').textContent=value.toLocaleString(undefined,{minimumFractionDigits:4,maximumFractionDigits:4});total+=value;});document.getElementById('bc-total').textContent=total.toLocaleString(undefined,{minimumFractionDigits:4,maximumFractionDigits:4});}
 function add(product,line={}){const row=body.insertRow(),i=index++;const c=cell(row,product.code);for(const [key,value] of Object.entries({product_id:product.id,goods_sent_note_item_id:line.goods_sent_note_item_id??''})){const input=document.createElement('input');input.type='hidden';input.name=`items[${i}][${key}]`;input.value=value;c.append(input);}cell(row,product.name);cell(row,product.unit);
 for(const key of ['shipment_number','shipment_date','quantity','unit_price','total_price','hs_code','country_code']){if(key==='total_price'){cell(row,'0').className='line-total text-end';continue;}const input=document.createElement('input');input.className='form-control form-control-sm';input.style.minWidth='120px';input.name=`items[${i}][${key}]`;input.dataset.field=key;input.setAttribute('aria-label',t[key]);input.value=line[key]??(['unit_price'].includes(key)?'0':'');if(key==='shipment_date')input.type='date';else if(['quantity','unit_price'].includes(key)){input.type='number';input.step='0.0001';input.min=key==='quantity'?'0.0001':'0';input.max='999999999.9999';input.oninput=totals;}else input.maxLength=key==='country_code'?3:key==='hs_code'?30:100;if(['shipment_number','shipment_date','quantity','unit_price'].includes(key))input.required=true;if((line.goods_sent_note_item_id)&&['shipment_number','shipment_date'].includes(key))input.readOnly=true;row.insertCell().append(input);}
 const remove=document.createElement('button');remove.type='button';remove.className='btn btn-outline-danger btn-sm';remove.textContent=t.remove;remove.onclick=()=>{row.remove();totals();};row.insertCell().append(remove);totals();}
 for(const line of lines){const product=products[line.product_id];if(product)add(product,line);}
 async function search(){pending?.abort();pending=new AbortController();const result=document.getElementById('picker-results'),status=document.getElementById('picker-status');result.replaceChildren();status.textContent=t.loading;const url=new URL(mode==='grn'?@json(route('super.bc-out.bc27out.gsns')):@json(route('super.bc-out.bc27out.products')));url.searchParams.set('search',document.getElementById('picker-search').value);if(mode==='grn')url.searchParams.set('customer_id',document.getElementById('customer').value);
 try{const response=await fetch(url,{headers:{Accept:'application/json'},signal:pending.signal});if(!response.ok)throw new Error();const data=await response.json();status.textContent=data.length?t.limit_notice:t.empty;for(const product of data){const row=result.insertRow();cell(row,product.shipment_number);cell(row,product.code);cell(row,product.name);cell(row,product.unit);const button=document.createElement('button');button.className='btn btn-primary btn-sm';button.textContent=t.select;button.onclick=()=>{add(product,mode==='grn'?product:{});modal.hide();};row.insertCell().append(button);}}catch(error){if(error.name!=='AbortError')status.textContent=t.load_failed;}}
 document.getElementById('choose-product').onclick=()=>{mode='product';modal.show();search();};document.getElementById('choose-grn').onclick=()=>{if(!document.getElementById('customer').value){alert(t.customer_required);return;}mode='grn';modal.show();search();};document.getElementById('picker-search-form').onsubmit=e=>{e.preventDefault();search();};document.getElementById('bc-form').addEventListener('submit',e=>{if(e.submitter?.value==='all'&&!body.rows.length){e.preventDefault();alert(t.items_required);}});
})();
</script>
